SELECT cd.cd_education_status, cd.cd_gender, SUM(COALESCE(s.total_profit,0)) - SUM(COALESCE(r.total_loss,0)) - SUM(COALESCE(d.total_discount_on_returns,0)) AS net_revenue, SUM(COALESCE(s.total_quantity,0)) AS total_sold_qty, SUM(COALESCE(r.total_return_qty,0)) AS total_return_qty, (SUM(COALESCE(r.total_loss,0)) / NULLIF(SUM(COALESCE(s.total_profit,0)),0)) * 100 AS loss_percent, RANK() OVER (ORDER BY (SUM(COALESCE(s.total_profit,0)) - SUM(COALESCE(r.total_loss,0)) - SUM(COALESCE(d.total_discount_on_returns,0))) DESC) AS revenue_rank FROM customer_demographics cd LEFT JOIN (SELECT ss_cdemo_sk, SUM(ss_net_profit) AS total_profit, SUM(ss_quantity) AS total_quantity FROM store_sales WHERE ss_sold_date_sk BETWEEN 2450000 AND 2452000 GROUP BY ss_cdemo_sk) s ON cd.cd_demo_sk = s.ss_cdemo_sk LEFT JOIN (SELECT sr_cdemo_sk, SUM(sr_net_loss) AS total_loss, SUM(sr_return_quantity) AS total_return_qty FROM store_returns WHERE sr_returned_date_sk BETWEEN 2450000 AND 2452000 GROUP BY sr_cdemo_sk) r ON cd.cd_demo_sk = r.sr_cdemo_sk LEFT JOIN (SELECT ss.ss_cdemo_sk AS cdemo_sk, SUM(ss.ss_ext_discount_amt) AS total_discount_on_returns FROM store_sales ss JOIN store_returns sr ON ss.ss_ticket_number = sr.sr_ticket_number AND ss.ss_item_sk = sr.sr_item_sk WHERE ss.ss_sold_date_sk BETWEEN 2450000 AND 2452000 AND sr.sr_returned_date_sk BETWEEN 2450000 AND 2452000 GROUP BY ss.ss_cdemo_sk) d ON cd.cd_demo_sk = d.cdemo_sk WHERE cd.cd_education_status IS NOT NULL GROUP BY cd.cd_education_status, cd.cd_gender HAVING (SUM(COALESCE(s.total_profit,0)) - SUM(COALESCE(r.total_loss,0)) - SUM(COALESCE(d.total_discount_on_returns,0))) > 0 ORDER BY net_revenue DESC LIMIT 10
